// examples/code/date-mentions/main.ts
var dates = [
  { label: "Today", offset: 0, detail: "\uC624\uB298" },
  { label: "Yesterday", offset: -1, detail: "\uC5B4\uC81C" },
  { label: "Tomorrow", offset: 1, detail: "\uB0B4\uC77C" }
];
var pad = (number, length = 2) => String(number).padStart(length, "0");
var plugin = {
  completions: {
    dates(_api, { query }) {
      const today = /* @__PURE__ */ new Date();
      return dates.filter(({ label }) => label.toLowerCase().startsWith(query.toLowerCase())).map(({ label, offset, detail }) => {
        const date = new Date(today);
        date.setDate(today.getDate() + offset);
        return {
          label,
          insertText: `${pad(date.getFullYear(), 4)}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`,
          detail
        };
      });
    }
  }
};
var main_default = plugin;
export {
  main_default as default
};
